#!/bin/sh
# Service-owned (not generated by sdk-kit): runs live/live_test.py against the real Datadog API.
# Skips (exit 0) without DATADOG_API_KEY / DATADOG_APP_KEY; otherwise installs ./python into
# $LIVE_VENV (default live/.venv) and runs the suite. Used by `make -C live live` and live.yml.
set -eu
here=$(cd "$(dirname "$0")" && pwd)
root=$(dirname "$here")
python=${PYTHON:-python3}
venv=${LIVE_VENV:-.venv}
case "$venv" in /*) ;; *) venv="$here/$venv" ;; esac

rc=0
"$python" "$here/live_test.py" --check-credentials || rc=$?
[ "$rc" -eq 78 ] && exit 0
[ "$rc" -eq 0 ] || exit "$rc"

[ -x "$venv/bin/python" ] || "$python" -m venv "$venv"
"$venv/bin/python" -m pip install --quiet --disable-pip-version-check "$root/python"
"$venv/bin/python" "$here/live_test.py"
